SELECT p.category, CASE WHEN p.price >= 1010 THEN 'high' WHEN p.price >= 520 THEN 'mid' ELSE 'low' END price_bucket, MAX(ss.sale_date) latest_sale_date, MAX(ss.revenue) max_revenue FROM store_sales ss LEFT OUTER JOIN products p ON ss.product_id = p.id JOIN stores s ON s.id = ss.store_id GROUP BY p.category, CASE WHEN p.price >= 1010 THEN 'high' WHEN p.price >= 520 THEN 'mid' ELSE 'low' END ORDER BY p.category ASC;
